// Generic Stack
class GenericStack<T> {
    private java.util.ArrayList<T> items = new java.util.ArrayList<>(); // object banao
    public void push(T item)  { items.add(item); }     // list mein add karo
    public T    pop()         { return items.isEmpty() ? null : items.remove(items.size()-1); } // value return karo
    public T    peek()        { return items.isEmpty() ? null : items.get(items.size()-1); } // value return karo
    public boolean isEmpty()  { return items.isEmpty(); } // value return karo
    public int  size()        { return items.size(); } // value return karo
}

// Generic method
public class GenericsDemo {                            // class define karo
    static <T extends Comparable<T>> T findMax(T[] arr) { // class level — object ki zaroorat nahi
        T max = arr[0];
        for (T item : arr) if (item.compareTo(max) > 0) max = item; // loop — repeat karo
        return max;                                    // value return karo
    }

    public static void main(String[] args) {           // main method — program yahan se shuru hota hai
        Pair<String, Integer> student = new Pair<>("Alice", 92); // object banao
        System.out.println(student);           // (Alice, 92)
        System.out.println(student.getFirst()); // Alice

        GenericStack<Integer> stack = new GenericStack<>(); // object banao
        stack.push(10); stack.push(20); stack.push(30);
        System.out.println("Pop: " + stack.pop()); // 30
        System.out.println("Peek: "+ stack.peek()); // 20

        Integer[] nums = {3, 7, 1, 9, 4};
        System.out.println("Max: " + findMax(nums)); // 9

        String[] words = {"banana","apple","cherry"};
        System.out.println("Max: " + findMax(words)); // cherry
    }
}

public class NumberPrograms {                          // class define karo
    static long factorial(int n) {                     // class level — object ki zaroorat nahi
        if (n <= 1) return 1;                          // condition check karo
        return n * factorial(n - 1);                   // value return karo
    }

    static boolean isArmstrong(int n) {                // class level — object ki zaroorat nahi
        String s   = String.valueOf(n);                // String variable
        int power  = s.length();                       // integer variable
        int sum    = 0;                                // integer variable
        for (char c : s.toCharArray())                 // loop — repeat karo
            sum += (int) Math.pow(c - '0', power);     // math operation
        return sum == n;                               // value return karo
    }

    static boolean isPerfect(int n) {                  // class level — object ki zaroorat nahi
        int sum = 1;                                   // integer variable
        for (int i = 2; i * i <= n; i++) {             // integer variable
            if (n % i == 0) {                          // condition check karo
                sum += i;
                if (i != n/i) sum += n/i;              // condition check karo
            }
        }
        return n > 1 && sum == n;                      // value return karo
    }

    public static void main(String[] args) {           // main method — program yahan se shuru hota hai
        // Factorial
        for (int i = 0; i <= 7; i++)                   // integer variable
            System.out.printf("%2d! = %d%n", i, factorial(i)); // output print karo

        // Armstrong
        System.out.print("Armstrong (1-500): ");       // output print karo
        for (int i = 1; i <= 500; i++)                 // integer variable
            if (isArmstrong(i)) System.out.print(i + " "); // output print karo
        System.out.println();                          // output print karo
        // 1 2 3 4 5 6 7 8 9 153 370 371 407

        // Perfect numbers
        System.out.print("Perfect (1-1000): ");        // output print karo
        for (int i = 2; i <= 1000; i++)                // integer variable
            if (isPerfect(i)) System.out.print(i + " "); // output print karo
        System.out.println();                          // output print karo
        // 6 28 496
    }
}

import java.util.*;

public class DataStructures {                          // class define karo
    public static void main(String[] args) {           // main method — program yahan se shuru hota hai
        // ── Stack ──────────────────────────────────────────
        Stack<Integer> stack = new Stack<>();          // object banao
        stack.push(10); stack.push(20); stack.push(30);
        System.out.println("Stack: "   + stack);       // output print karo
        System.out.println("Pop: "     + stack.pop());   // 30
        System.out.println("Peek: "    + stack.peek());  // 20
        System.out.println("Empty: "   + stack.isEmpty()); // false

        // ── Queue ──────────────────────────────────────────
        Queue<String> queue = new LinkedList<>();      // object banao
        queue.add("Alice"); queue.add("Bob"); queue.add("Charlie"); // list mein add karo
        System.out.println("Queue: "   + queue);       // output print karo
        System.out.println("Poll: "    + queue.poll()); // Alice (removes)
        System.out.println("Peek: "    + queue.peek()); // Bob (doesn't remove)

        // ── Deque (Double-ended queue) ─────────────────────
        Deque<Integer> deque = new ArrayDeque<>();     // object banao
        deque.addFirst(10); deque.addLast(20);
        deque.addFirst(5);  deque.addLast(25);
        System.out.println("Deque: "   + deque); // [5,10,20,25]

        // ── PriorityQueue (min-heap) ───────────────────────
        PriorityQueue<Integer> pq = new PriorityQueue<>(); // object banao
        pq.add(30); pq.add(10); pq.add(20);            // list mein add karo
        while (!pq.isEmpty())                          // jab tak condition True ho
            System.out.print(pq.poll() + " "); // 10 20 30
        System.out.println();                          // output print karo

        // ── HashSet ────────────────────────────────────────
        HashSet<String> set = new HashSet<>();         // object banao
        set.add("apple"); set.add("banana"); set.add("apple"); // duplicate ignored
        System.out.println("Set: " + set);  // {apple, banana}
    }
}

import java.util.Arrays;   // for Arrays.sort()

public class StringProblems {                          // class define karo
    // Check if string is palindrome (reads same forward and backward)
    static boolean isPalindromeStr(String s) {         // class level — object ki zaroorat nahi
        s = s.toLowerCase().replaceAll("[^a-z0-9]", "");  // normalize: lowercase, remove non-alphanumeric
        String reversed = new StringBuilder(s).reverse().toString();  // reverse the string
        return s.equals(reversed);   // compare original with reversed
    }

    // Check if number is palindrome
    static boolean isPalindromeNum(int n) {            // class level — object ki zaroorat nahi
        String s = String.valueOf(n);    // convert number to string
        String r = new StringBuilder(s).reverse().toString();  // reverse
        return s.equals(r);              // compare
    }

    // Check if two strings are anagrams (same letters, different order)
    static boolean isAnagram(String a, String b) {     // class level — object ki zaroorat nahi
        char[] ca = a.toLowerCase().toCharArray();  // convert to char arrays
        char[] cb = b.toLowerCase().toCharArray();
        Arrays.sort(ca);   // sort both alphabetically
        Arrays.sort(cb);                               // array sort karo
        return Arrays.equals(ca, cb);  // sorted anagrams will be identical
    }

    // Reverse words in a sentence
    static String reverseWords(String s) {             // class level — object ki zaroorat nahi
        String[] words = s.split(" ");   // split by spaces into word array
        StringBuilder sb = new StringBuilder();        // object banao
        for (int i = words.length - 1; i >= 0; i--)   // iterate backwards
            sb.append(words[i]).append(" ");            // add each word with space
        return sb.toString().trim();                    // remove trailing space
    }

    // Count vowels in string
    static int countVowels(String s) {                 // class level — object ki zaroorat nahi
        int count = 0;                                 // integer variable
        for (char c : s.toLowerCase().toCharArray())   // check each character
            if ("aeiou".indexOf(c) >= 0) count++;      // if it's a vowel, count it
        return count;                                  // value return karo
    }

    public static void main(String[] args) {           // main method — program yahan se shuru hota hai
        // Test palindromes
        String[] words = {"madam", "hello", "racecar", "level", "A man a plan a canal Panama"};
        for (String w : words)                         // loop — repeat karo
            System.out.printf("%-30s: %s%n", w, isPalindromeStr(w) ? "Palindrome" : "Not"); // output print karo

        System.out.println();                          // output print karo
        // Test numbers
        int[] nums = {121, 12321, 123, 1001};
        for (int n : nums)                             // loop — repeat karo
            System.out.printf("%5d: %s%n", n, isPalindromeNum(n) ? "Palindrome" : "Not"); // output print karo

        System.out.println();                          // output print karo
        System.out.println(isAnagram("listen", "silent"));  // true
        System.out.println(reverseWords("Hello World Java")); // Java World Hello
        System.out.println(countVowels("Hello World"));       // 3
    }
}

import java.util.Arrays;   // for Arrays.toString()

public class MatrixOps {                               // class define karo
    // Multiply two matrices: C[i][j] = sum of A[i][k] * B[k][j] for all k
    // Rule: columns of A must equal rows of B
    static int[][] multiply(int[][] A, int[][] B) {    // class level — object ki zaroorat nahi
        int n = A.length;      // rows of A (= rows of result C)
        int m = B[0].length;   // columns of B (= columns of result C)
        int p = B.length;      // rows of B (= columns of A, must match)
        int[][] C = new int[n][m];      // result matrix, initialized to 0
        for (int i = 0; i < n; i++)     // for each row of A
            for (int j = 0; j < m; j++) // for each column of B
                for (int k = 0; k < p; k++)   // dot product
                    C[i][j] += A[i][k] * B[k][j];  // accumulate sum
        return C;                                      // value return karo
    }

    // Transpose: swap rows and columns (T[j][i] = M[i][j])
    static int[][] transpose(int[][] M) {              // class level — object ki zaroorat nahi
        int rows = M.length, cols = M[0].length;       // integer variable
        int[][] T = new int[cols][rows];   // dimensions are swapped
        for (int i = 0; i < rows; i++)                 // integer variable
            for (int j = 0; j < cols; j++)             // integer variable
                T[j][i] = M[i][j];         // swap row and column index
        return T;                                      // value return karo
    }

    // Print matrix with a label
    static void print(int[][] M, String label) {       // class level — object ki zaroorat nahi
        System.out.println(label + ":");               // output print karo
        for (int[] row : M)                            // loop — repeat karo
            System.out.println("  " + Arrays.toString(row));  // print each row
    }

    public static void main(String[] args) {           // main method — program yahan se shuru hota hai
        int[][] A = {{1,2,3},{4,5,6},{7,8,9}};   // 3×3 matrix A
        int[][] B = {{9,8,7},{6,5,4},{3,2,1}};   // 3×3 matrix B

        print(A, "Matrix A");
        print(B, "Matrix B");
        print(multiply(A, B),   "A × B");        // matrix multiplication
        print(transpose(A),     "Transpose A");  // swap rows and columns
    }
}

import java.util.Arrays;

public class BinarySearch {                            // class define karo
    // Iterative
    static int binarySearch(int[] arr, int target) {   // class level — object ki zaroorat nahi
        int low = 0, high = arr.length - 1;            // integer variable
        while (low <= high) {                          // jab tak condition True ho
            int mid = low + (high - low) / 2;          // integer variable
            if      (arr[mid] == target) return mid;   // condition check karo
            else if (arr[mid] < target)  low  = mid + 1; // condition check karo
            else                         high = mid - 1; // jab condition False ho
        }
        return -1;                                     // value return karo
    }

    // Recursive
    static int binarySearchRec(int[] arr, int target, int low, int high) { // class level — object ki zaroorat nahi
        if (low > high) return -1;                     // condition check karo
        int mid = (low + high) / 2;                    // integer variable
        if      (arr[mid] == target) return mid;       // condition check karo
        else if (arr[mid] < target)  return binarySearchRec(arr, target, mid+1, high); // condition check karo
        else                          return binarySearchRec(arr, target, low, mid-1); // jab condition False ho
    }

    public static void main(String[] args) {           // main method — program yahan se shuru hota hai
        int[] arr = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};
        System.out.println("Array: " + Arrays.toString(arr)); // output print karo

        System.out.println("Search 23: " + binarySearch(arr, 23));    // 5
        System.out.println("Search 99: " + binarySearch(arr, 99));    // -1
        System.out.println("Rec 56:    " + binarySearchRec(arr, 56, 0, arr.length-1)); // 7

        // Built-in
        System.out.println("Arrays.binarySearch 16: " + Arrays.binarySearch(arr, 16)); // 4
    }
}

