public class MergeSort {                               // class define karo
    static void merge(int[] arr, int l, int m, int r) { // class level — object ki zaroorat nahi
        int n1 = m - l + 1, n2 = r - m;                // integer variable
        int[] L = new int[n1], R = new int[n2];        // object banao
        for (int i = 0; i < n1; i++) L[i] = arr[l + i]; // integer variable
        for (int j = 0; j < n2; j++) R[j] = arr[m + 1 + j]; // integer variable
        int i = 0, j = 0, k = l;                       // integer variable
        while (i < n1 && j < n2) arr[k++] = (L[i] <= R[j]) ? L[i++] : R[j++]; // jab tak condition True ho
        while (i < n1) arr[k++] = L[i++];              // jab tak condition True ho
        while (j < n2) arr[k++] = R[j++];              // jab tak condition True ho
    }
    static void mergeSort(int[] arr, int l, int r) {   // class level — object ki zaroorat nahi
        if (l < r) {                                   // condition check karo
            int m = (l + r) / 2;                       // integer variable
            mergeSort(arr, l, m);
            mergeSort(arr, m + 1, r);
            merge(arr, l, m, r);
        }
    }
    public static void main(String[] args) {           // main method — program yahan se shuru hota hai
        int[] arr = {64, 25, 12, 22, 11};
        mergeSort(arr, 0, arr.length - 1);
        for (int x : arr) System.out.print(x + " "); // 11 12 22 25 64
    }
}

public class QuickSort {                               // class define karo
    static int partition(int[] arr, int low, int high) { // class level — object ki zaroorat nahi
        int pivot = arr[high], i = low - 1;            // integer variable
        for (int j = low; j < high; j++) {             // integer variable
            if (arr[j] <= pivot) { i++; int t=arr[i]; arr[i]=arr[j]; arr[j]=t; } // integer variable
        }
        int t=arr[i+1]; arr[i+1]=arr[high]; arr[high]=t; // integer variable
        return i + 1;                                  // value return karo
    }
    static void quickSort(int[] arr, int low, int high) { // class level — object ki zaroorat nahi
        if (low < high) {                              // condition check karo
            int pi = partition(arr, low, high);        // integer variable
            quickSort(arr, low, pi - 1);
            quickSort(arr, pi + 1, high);
        }
    }
    public static void main(String[] args) {           // main method — program yahan se shuru hota hai
        int[] arr = {10, 7, 8, 9, 1, 5};
        quickSort(arr, 0, arr.length - 1);
        for (int x : arr) System.out.print(x + " ");   // output print karo
    }
}

