public class HappyNumber {                             // class define karo
    static int sumOfSquares(int n) {                   // class level — object ki zaroorat nahi
        int sum = 0;                                   // integer variable
        while (n > 0) { int d = n % 10; sum += d * d; n /= 10; } // integer variable
        return sum;                                    // value return karo
    }
    static boolean isHappy(int n) {                    // class level — object ki zaroorat nahi
        int slow = n, fast = sumOfSquares(n);          // integer variable
        while (fast != 1 && slow != fast) {            // jab tak condition True ho
            slow = sumOfSquares(slow);
            fast = sumOfSquares(sumOfSquares(fast));
        }
        return fast == 1;                              // value return karo
    }
    public static void main(String[] args) {           // main method — program yahan se shuru hota hai
        for (int i = 1; i <= 20; i++)                  // integer variable
            if (isHappy(i)) System.out.print(i + " "); // output print karo
        // 1 7 10 13 19
    }
}

