        int n = 5;                                     // integer variable
        // Solid pyramid
        System.out.println("Solid Pyramid:");          // output print karo
        for (int i = 1; i <= n; i++) {                 // integer variable
            for (int s = 1; s <= n - i; s++) System.out.print(" "); // output print karo
            for (int j = 1; j <= 2*i-1; j++) System.out.print("*"); // output print karo
            System.out.println();                      // output print karo
        }
